    "inlineSchema": "generator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────\n//  Enums del dominio\n// ─────────────────────────────────────────────\n\nenum Rol {\n  DUENO\n  STAFF\n  CLIENTE\n}\n\nenum EstadoCita {\n  PENDIENTE\n  CONFIRMADA\n  CANCELADA\n  COMPLETADA\n}\n\nenum Plan {\n  FREE\n  PRO\n}\n\nenum EstadoSuscripcion {\n  ACTIVA\n  CANCELADA\n  VENCIDA\n}\n\n// ─────────────────────────────────────────────\n//  Identidad (reutilizado de M3: auth + roles)\n// ─────────────────────────────────────────────\n\nmodel Usuario {\n  id       Int      @id @default(autoincrement())\n  nombre   String\n  email    String   @unique\n  password String\n  rol      Rol      @default(CLIENTE)\n  creadoEn DateTime @default(now())\n\n  // Un usuario DUENO administra sus negocios (tenant)\n  negocios         Negocio[]\n  // Un usuario CLIENTE reserva citas\n  citasComoCliente Cita[]    @relation(\"CitasCliente\")\n  // Perfil extendido (se construye en C2)\n  perfil           Perfil?\n\n  @@map(\"usuarios\")\n}\n\nmodel Perfil {\n  id        Int     @id @default(autoincrement())\n  telefono  String?\n  bio       String?\n  avatarUrl String?\n  usuarioId Int     @unique\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n\n  @@map(\"perfiles\")\n}\n\n// ─────────────────────────────────────────────\n//  Tenant: el negocio de Don Pepe\n// ─────────────────────────────────────────────\n\nmodel Negocio {\n  id          Int      @id @default(autoincrement())\n  nombre      String\n  descripcion String?\n  telefono    String?\n  direccion   String?\n  creadoEn    DateTime @default(now())\n\n  // Dueño (tenant owner)\n  duenoId Int\n  dueno   Usuario @relation(fields: [duenoId], references: [id])\n\n  // Relaciones del dominio\n  profesionales Profesional[]\n  servicios     Servicio[]\n  citas         Cita[]\n  suscripcion   Suscripcion?\n  configuracion Configuracion?\n\n  @@index([duenoId])\n  @@map(\"negocios\")\n}\n\n// ─────────────────────────────────────────────\n//  Quien atiende (barberos de Don Pepe)\n// ─────────────────────────────────────────────\n\nmodel Profesional {\n  id           Int      @id @default(autoincrement())\n  nombre       String\n  especialidad String?\n  activo       Boolean  @default(true)\n  creadoEn     DateTime @default(now())\n\n  negocioId Int\n  negocio   Negocio @relation(fields: [negocioId], references: [id])\n\n  // M-a-N: un profesional ofrece varios servicios\n  servicios ServicioProfesional[]\n  citas     Cita[]\n\n  @@index([negocioId])\n  @@map(\"profesionales\")\n}\n\n// ─────────────────────────────────────────────\n//  Lo que se ofrece (corte, barba, tinte...)\n// ─────────────────────────────────────────────\n\nmodel Servicio {\n  id          Int      @id @default(autoincrement())\n  nombre      String\n  duracionMin Int\n  precio      Decimal  @db.Decimal(10, 2)\n  activo      Boolean  @default(true)\n  creadoEn    DateTime @default(now())\n\n  negocioId Int\n  negocio   Negocio @relation(fields: [negocioId], references: [id])\n\n  // M-a-N: un servicio lo dan varios profesionales\n  profesionales ServicioProfesional[]\n  citas         Cita[]\n\n  @@index([negocioId])\n  @@map(\"servicios\")\n}\n\n// Tabla intermedia explícita de la relación muchos-a-muchos\nmodel ServicioProfesional {\n  servicioId    Int\n  profesionalId Int\n  servicio      Servicio    @relation(fields: [servicioId], references: [id])\n  profesional   Profesional @relation(fields: [profesionalId], references: [id])\n\n  @@id([servicioId, profesionalId])\n  @@map(\"servicio_profesional\")\n}\n\n// ─────────────────────────────────────────────\n//  El núcleo: la reserva sin cruces\n// ─────────────────────────────────────────────\n\nmodel Cita {\n  id       Int        @id @default(autoincrement())\n  fecha    DateTime\n  estado   EstadoCita @default(PENDIENTE)\n  notas    String?\n  creadoEn DateTime   @default(now())\n\n  negocioId     Int\n  negocio       Negocio     @relation(fields: [negocioId], references: [id])\n  clienteId     Int\n  cliente       Usuario     @relation(\"CitasCliente\", fields: [clienteId], references: [id])\n  servicioId    Int\n  servicio      Servicio    @relation(fields: [servicioId], references: [id])\n  profesionalId Int\n  profesional   Profesional @relation(fields: [profesionalId], references: [id])\n\n  @@index([negocioId])\n  @@index([profesionalId, fecha])\n  @@map(\"citas\")\n}\n\n// ─────────────────────────────────────────────\n//  Monetización (Stripe, se conecta en C3)\n// ─────────────────────────────────────────────\n\nmodel Suscripcion {\n  id                   Int               @id @default(autoincrement())\n  plan                 Plan              @default(FREE)\n  estado               EstadoSuscripcion @default(ACTIVA)\n  stripeCustomerId     String?\n  stripeSubscriptionId String?\n  vigenteHasta         DateTime?\n  creadoEn             DateTime          @default(now())\n\n  negocioId Int     @unique\n  negocio   Negocio @relation(fields: [negocioId], references: [id])\n\n  @@map(\"suscripciones\")\n}\n\n// ─────────────────────────────────────────────\n//  Configuración del sistema por negocio (C2)\n// ─────────────────────────────────────────────\n\nmodel Configuracion {\n  id              Int      @id @default(autoincrement())\n  horaApertura    String   @default(\"09:00\")\n  horaCierre      String   @default(\"18:00\")\n  zonaHoraria     String   @default(\"America/Bogota\")\n  duracionDefault Int      @default(30)\n  actualizadoEn   DateTime @updatedAt\n\n  negocioId Int     @unique\n  negocio   Negocio @relation(fields: [negocioId], references: [id])\n\n  @@map(\"configuraciones\")\n}\n",
